steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      query {
        issues(first: 20, query: \"Renew SSO certificate\") {
          nodes {
            id
            identifier
            title
            description
            priority
            assignee {
              id
              name
              email
            }
            creator {
              id
              name
              email
            }
          }
        }
      }
    "
  }'
